  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 21, $j$6.1 Acids, Bases and pH$j$, $j${"readings": [{"title": "Proverbs 25 (King James Version)", "url": "/portal/bible/Proverbs/25"}], "body": "Acids and bases are among the most important groups of compounds. Proverbs 25:20 mentions vinegar poured upon nitre, an everyday picture of a lively chemical reaction. Vinegar is a weak acid, and acids react with many substances.\n\nAn acid, according to Arrhenius, produces hydrogen ions in water. A base produces hydroxide ions in water. A broader definition by Bronsted and Lowry says an acid is a proton donor and a base is a proton acceptor. Acids taste sour, turn blue litmus paper red, and react with some metals to produce hydrogen gas. Bases taste bitter, feel slippery, and turn red litmus paper blue. Never taste or touch chemicals in a lab. Common acids include hydrochloric acid, sulfuric acid, nitric acid and acetic acid in vinegar. Common bases include sodium hydroxide, ammonia and the baking soda in your kitchen.\n\nA strong acid or base ionizes almost completely in water, while a weak acid or base ionizes only partly. Strong and weak describe how much it ionizes, and concentrated and dilute describe how much is dissolved. Both strong and weak acids can be dangerous, and strong ones are especially hazardous.\n\nThe pH scale measures how acidic or basic a solution is, usually from 0 to 14. A pH of 7 is neutral, as in pure water. A pH below 7 is acidic, and a pH above 7 is basic. Each whole number change in pH is a tenfold change in hydrogen ion concentration, so a solution with pH 3 is ten times more acidic than one with pH 4. Lemon juice is about pH 2, milk about 6.5, blood about 7.4 and household ammonia about 11. Indicators such as litmus, phenolphthalein and universal indicator change color with pH.\n\nIn a neutralization reaction, an acid and a base react to form a salt and water. Hydrochloric acid plus sodium hydroxide yields sodium chloride plus water. Neutralization is used in antacids, in treating spills and in titrations. At home, never mix cleaners such as bleach and ammonia, because toxic gases can form.\n\nYour task: (1) Compare acids and bases using three properties each. (2) Explain what pH 3 compared with pH 5 means. (3) Write a word equation for a neutralization reaction.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Proverbs 25:20 mentions vinegar poured upon nitre, an everyday picture of a lively reaction. Vinegar is a weak acid.\n\nNow watch this. An acid produces hydrogen ions in water. A base produces hydroxide ions. Bronsted and Lowry say an acid donates a proton and a base accepts a proton. Acids taste sour, turn blue litmus red and react with some metals to make hydrogen. Bases taste bitter, feel slippery and turn red litmus blue. Never taste or touch lab chemicals.\n\nStrong acids and bases ionize almost completely. Weak ones ionize partly. Strong and weak are not the same as concentrated and dilute.\n\nThe pH scale runs from 0 to 14. Seven is neutral. Below 7 is acidic. Above 7 is basic. Each whole number is a tenfold change. Lemon juice is about 2. Milk is about 6.5. Blood is about 7.4. Ammonia is about 11.\n\nNeutralization produces a salt and water. Hydrochloric acid plus sodium hydroxide yields sodium chloride and water.\n\nAt home, never mix bleach with ammonia or other cleaners.\n\nYour task is to compare acids and bases, explain pH 3 versus pH 5 and write a neutralization equation. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.1 Acids, Bases and pH$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 22, $j$6.2 Reaction Rates and Chemical Equilibrium$j$, $j${"readings": [{"title": "Ecclesiastes 3 (King James Version)", "url": "/portal/bible/Ecclesiastes/3"}], "body": "Some reactions happen in an instant, like an explosion, and others take years, like rusting. The rate of a reaction is how fast reactants are used up or products are formed. Ecclesiastes 3:1 says, To every thing there is a season, and a time to every purpose under the heaven. Chemists study the timing of reactions so they can speed up helpful ones and slow down harmful ones.\n\nCollision theory says that a reaction occurs when particles collide with enough energy and the right orientation. The minimum energy needed is called the activation energy. Several factors change the rate. Raising the temperature makes particles move faster and collide more often and with more energy. Increasing concentration, or pressure for gases, means more collisions. Increasing surface area, such as by crushing a solid, exposes more particles. A catalyst speeds up a reaction by providing a path with lower activation energy and is not used up. Enzymes in our bodies are biological catalysts. Food is stored in a refrigerator to slow reactions that cause spoilage.\n\nMany reactions are reversible, meaning products can turn back into reactants. In a closed system, a reversible reaction can reach chemical equilibrium, the point at which the forward and reverse reactions occur at equal rates. At equilibrium the amounts of reactants and products stay constant, but the reactions have not stopped. They continue in both directions at the same pace. An equilibrium is shown with a double arrow, or in words as reversible.\n\nLe Chatelier's principle says that if a system at equilibrium is disturbed, it shifts to partly counteract the change. Adding more reactant shifts the reaction toward products. Removing a product also shifts it toward products. Raising the temperature favors the endothermic direction. Increasing the pressure on a gas reaction favors the side with fewer gas particles. The industrial production of ammonia for fertilizer uses these ideas to improve the yield. Colossians 1:17 says of Christ, by him all things consist.\n\nYour task: (1) List four ways to speed up a reaction. (2) Explain what a catalyst does. (3) Describe what happens to the system if more reactant is added to a reaction at equilibrium.\n\nFlorida standards: SC.912.P.8.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.8", "script": "Welcome back. Listen, Ecclesiastes 3:1 says, To every thing there is a season, and a time to every purpose under the heaven. Chemists study timing so they can speed up helpful reactions and slow down harmful ones.\n\nNow watch this. Collision theory says a reaction occurs when particles collide with enough energy and the right orientation. The minimum energy is the activation energy.\n\nTo speed up a reaction, raise the temperature, increase the concentration, increase the surface area or add a catalyst. A catalyst lowers the activation energy and is not used up. Enzymes are biological catalysts. We refrigerate food to slow spoilage.\n\nMany reactions are reversible. At chemical equilibrium the forward and reverse reactions happen at equal rates. The amounts stay constant, but the reactions have not stopped.\n\nLe Chatelier's principle says that if a system at equilibrium is disturbed, it shifts to partly counteract the change. Add reactant and it shifts toward products. Remove a product and it shifts toward products. Colossians 1:17 says of Christ, by him all things consist.\n\nYour task is to list four ways to speed up a reaction, explain a catalyst and describe adding reactant at equilibrium. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.2 Reaction Rates and Chemical Equilibrium$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 23, $j$6.3 Oxidation, Reduction and Electrochemistry$j$, $j${"readings": [{"title": "Malachi 3 (King James Version)", "url": "/portal/bible/Malachi/3"}], "body": "Many important reactions involve the transfer of electrons. These are oxidation reduction reactions, called redox reactions for short. Oxidation is the loss of electrons, and reduction is the gain of electrons. A memory aid is OIL RIG: Oxidation Is Loss, Reduction Is Gain. The two always occur together, because electrons lost by one substance are gained by another. The substance that is oxidized is the reducing agent, and the substance that is reduced is the oxidizing agent.\n\nOxidation numbers help track electrons. A pure element has an oxidation number of zero. A simple ion has an oxidation number equal to its charge. If a number increases, the atom was oxidized, and if it decreases, the atom was reduced. When zinc metal is placed in a copper solution, zinc loses 2 electrons and goes into solution, and copper ions gain 2 electrons and form copper metal. Zinc is oxidized and copper is reduced.\n\nRedox reactions are all around us. Rusting is the slow oxidation of iron in the presence of water and oxygen. Combustion and cellular respiration are redox reactions. Metals can be protected by painting, coating with zinc in galvanizing, or keeping them dry. Bleach works by oxidation.\n\nElectrochemistry is the study of how chemical reactions and electrical energy are related. A galvanic cell, or battery, uses a spontaneous redox reaction to produce electric current. Oxidation takes place at the anode and reduction at the cathode, and electrons flow through a wire from anode to cathode. Electrolysis does the reverse: it uses electricity to force a nonspontaneous reaction, as in plating metals or separating aluminum from its ore.\n\nScripture often uses refining as a picture of God's work. Malachi 3:3 says, And he shall sit as a refiner and purifier of silver. 1 Peter 1:7 says that the trial of your faith is much more precious than of gold that perisheth, though it be tried with fire.\n\nYour task: (1) State what OIL RIG means. (2) Identify what is oxidized and reduced when zinc reacts with copper ions. (3) Explain how a battery produces electric current.\n\nFlorida standards: SC.912.P.10.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.10", "script": "Welcome back. Listen, Malachi 3:3 says, And he shall sit as a refiner and purifier of silver. And 1 Peter 1:7 says the trial of your faith is much more precious than of gold that perisheth, though it be tried with fire. Scripture uses refining to picture God's work.\n\nNow watch this. Redox reactions transfer electrons. Oxidation is loss of electrons. Reduction is gain of electrons. OIL RIG: Oxidation Is Loss, Reduction Is Gain. They always happen together.\n\nThe substance oxidized is the reducing agent. The substance reduced is the oxidizing agent.\n\nWhen zinc is placed in a copper solution, zinc loses 2 electrons and copper ions gain 2. Zinc is oxidized. Copper is reduced.\n\nRusting is slow oxidation of iron with water and oxygen. Combustion and cellular respiration are redox reactions. Paint and zinc coatings protect metal.\n\nA galvanic cell, or battery, uses a spontaneous redox reaction to make current. Oxidation at the anode, reduction at the cathode, and electrons flow through the wire. Electrolysis uses electricity to force a reaction.\n\nYour task is to explain OIL RIG, identify what is oxidized and reduced and explain how a battery works. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.3 Oxidation, Reduction and Electrochemistry$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 24, $j$6.4 Nuclear and Organic Chemistry, and Stewardship of Creation$j$, $j${"readings": [{"title": "Psalm 24 (King James Version)", "url": "/portal/bible/Psalms/24"}], "body": "Chemistry reaches from the nucleus of the atom to the molecules of life. Psalm 24:1 says, The earth is the LORD'S, and the fulness thereof; the world, and they that dwell therein. Genesis 2:15 says that the LORD God took the man, and put him into the garden of Eden to dress it and to keep it. Chemists are called, like all people, to use creation wisely and protect it.\n\nNuclear chemistry studies changes in the nucleus. Some nuclei are unstable and give off radiation in a process called radioactive decay. Alpha particles are helium nuclei with 2 protons and 2 neutrons, beta particles are fast electrons and gamma rays are high energy radiation. Gamma rays penetrate the most and alpha particles the least. The half life of an isotope is the time for half of a sample to decay. If an isotope has a half life of 5 years, 80 grams will become 40 grams after 5 years, 20 grams after 10 years and 10 grams after 15 years. Fission splits a heavy nucleus such as uranium, releasing great energy, and is used in nuclear power plants. Fusion joins light nuclei and powers the Sun. Radioisotopes are used in medicine, in smoke detectors and in dating. Radiation can also harm living tissue, so it must be handled with care and respect. Isaiah 2:4 speaks of the hope of turning weapons into plowshares.\n\nOrganic chemistry is the study of carbon compounds. Carbon forms four bonds and can make long chains and rings, which is why there are millions of organic compounds. Hydrocarbons contain only carbon and hydrogen, such as methane, ethane and propane. Functional groups give families of compounds their properties, such as alcohols, organic acids and amines. The large molecules of life are carbohydrates, lipids, proteins and nucleic acids, and they are built from smaller units.\n\nChemistry serves people through medicine, food, clean water, fuels, fertilizers and materials. It also raises responsibilities: preventing pollution, using resources wisely, recycling, disposing of chemicals safely and telling the truth about risks. Careers include chemist, chemical engineer, pharmacist, nurse, physician, environmental scientist, forensic scientist and teacher.\n\nYour task: (1) Describe alpha, beta and gamma radiation. (2) Calculate how much of a 40 gram sample remains after 2 half lives. (3) Explain two ways a Christian chemist can practice stewardship.\n\nFlorida standards: SC.912.P.10, SC.912.L.18.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SC.912.P.10, SC.912.L.18", "script": "Welcome back. Listen, Psalm 24:1 says, The earth is the LORD'S, and the fulness thereof; the world, and they that dwell therein. And Genesis 2:15 says the man was put in the garden to dress it and to keep it. Chemists are called, like all people, to use creation wisely and protect it.\n\nNow watch this. Nuclear chemistry studies the nucleus. Unstable nuclei give off radiation by radioactive decay. Alpha particles are helium nuclei. Beta particles are fast electrons. Gamma rays are high energy radiation. Gamma penetrates the most.\n\nA half life is the time for half of a sample to decay. With a half life of 5 years, 80 grams becomes 40, then 20, then 10. Fission splits heavy nuclei. Fusion joins light nuclei and powers the Sun. Radioisotopes are used in medicine and smoke detectors. Radiation can harm tissue, so handle with care.\n\nOrganic chemistry is the chemistry of carbon. Carbon forms four bonds and makes chains and rings. Hydrocarbons contain carbon and hydrogen. Carbohydrates, lipids, proteins and nucleic acids are the molecules of life.\n\nChemistry serves through medicine, food, clean water and materials. It also calls for preventing pollution, safe disposal and truthful reporting.\n\nYour task is to describe the three radiations, calculate a half life and explain stewardship. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$6.4 Nuclear and Organic Chemistry, and Stewardship of Creation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 6, $j$Assessment 6: Acids and Bases, Redox, Nuclear and Organic Chemistry and Stewardship$j$, $j${"prompt": "Write a report of at least 250 words on the final topics of chemistry. Use complete sentences and label each part. Psalm 24:1 says, The earth is the LORD'S, and the fulness thereof; the world, and they that dwell therein.\n\nPart 1: Compare acids and bases and explain the pH scale. State the pH of a neutral solution and explain what a pH of 2 means compared to a pH of 4. Write a word equation for a neutralization reaction and explain a safety rule for household cleaners.\nPart 2: Explain collision theory and four factors that change reaction rate. Explain what a catalyst does and what chemical equilibrium means. Apply Le Chatelier's principle to adding reactant.\nPart 3: Define oxidation, reduction and OIL RIG. Explain rusting and how a battery produces current.\nPart 4: Describe alpha, beta and gamma radiation. Calculate how much of an 80 gram sample remains after 3 half lives. Name one benefit and one risk of nuclear technology.\nPart 5: Explain how Psalm 24:1 and Genesis 2:15 guide a chemist in the use of creation, and name a chemistry career you could serve in.", "rubric": "100 points. Part 1: 25 points. Part 2: 25 points. Part 3: 15 points. Part 4: 20 points. Part 5: 10 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 6: Acids and Bases, Redox, Nuclear and Organic Chemistry and Stewardship$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 6, $j$Discussion 6: The Earth Is the LORD'S$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes one way chemistry has blessed your life, such as medicine, clean water, food or energy, (2) describes one responsibility chemists and citizens have to protect creation, such as safe disposal, recycling or preventing pollution, (3) explains how seeing the order in matter strengthens your faith or your respect for the Creator, and (4) connects your answer to Psalm 24:1, Genesis 2:15, Colossians 1:17 or Malachi 3:3. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How should Christians think about using technologies that can be used for both good and harm? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 6: The Earth Is the LORD'S$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 26, $j$Check 6.1: Acids, Bases and pH$j$, $j${"questions": [{"q": "A solution with a pH of 7 is:", "options": ["Basic", "Acidic", "Radioactive", "Neutral"]}, {"q": "A solution with pH 3 compared to pH 5 is:", "options": ["100 times more acidic", "Ten times more basic", "The same", "Twice as acidic"]}, {"q": "An acid and a base react in neutralization to form:", "options": ["Two bases", "A salt and water", "Two acids", "Only gas"]}, {"q": "According to Bronsted and Lowry, an acid is a:", "options": ["Proton acceptor", "Proton donor", "Neutron acceptor", "Electron donor"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Acids, Bases and pH$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,0,1,1}'::int[], array[$j$Seven is neutral.$j$,$j$Two pH units is a factor of 100.$j$,$j$Neutralization forms salt and water.$j$,$j$Acids donate protons.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.1: Acids, Bases and pH$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 27, $j$Check 6.2: Reaction Rates and Chemical Equilibrium$j$, $j${"questions": [{"q": "The minimum energy needed for a reaction to occur is the:", "options": ["Activation energy", "Atomic number", "Molar mass", "Heat of fusion"]}, {"q": "A catalyst speeds up a reaction by:", "options": ["Removing reactants", "Raising the activation energy", "Being consumed", "Lowering the activation energy"]}, {"q": "At chemical equilibrium, the forward and reverse reaction rates are:", "options": ["Equal", "Zero", "Doubled each second", "Different"]}, {"q": "Crushing a solid reactant speeds up a reaction because it increases:", "options": ["Surface area", "Atomic number", "Molar mass", "Activation energy"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Reaction Rates and Chemical Equilibrium$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,0,0}'::int[], array[$j$Reactions must overcome the activation energy.$j$,$j$It provides an easier path.$j$,$j$The reactions continue at equal rates.$j$,$j$More surface exposes more particles.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.2: Reaction Rates and Chemical Equilibrium$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 28, $j$Check 6.3: Oxidation, Reduction and Electrochemistry$j$, $j${"questions": [{"q": "Oxidation is the:", "options": ["Gain of neutrons", "Gain of electrons", "Loss of electrons", "Loss of protons"]}, {"q": "In a galvanic cell, reduction occurs at the:", "options": ["Wire", "Cathode", "Salt bridge only", "Anode"]}, {"q": "Rusting is an example of:", "options": ["Oxidation of iron", "Sublimation", "Reduction of iron", "Neutralization"]}, {"q": "Using electricity to force a nonspontaneous reaction is:", "options": ["Dilution", "Distillation", "Combustion", "Electrolysis"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Oxidation, Reduction and Electrochemistry$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,1,0,3}'::int[], array[$j$OIL: Oxidation Is Loss.$j$,$j$Reduction happens at the cathode.$j$,$j$Iron loses electrons to oxygen.$j$,$j$Electrolysis drives reactions with current.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.3: Oxidation, Reduction and Electrochemistry$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 29, $j$Check 6.4: Nuclear and Organic Chemistry, and Stewardship of Creation$j$, $j${"questions": [{"q": "A 40 gram sample of an isotope after 2 half lives has how many grams left?", "options": ["5", "30", "20", "10"]}, {"q": "The type of radiation that is a helium nucleus is:", "options": ["X ray", "Gamma", "Alpha", "Beta"]}, {"q": "The joining of light nuclei, as in the Sun, is called:", "options": ["Electrolysis", "Fission", "Combustion", "Fusion"]}, {"q": "Organic chemistry is the study of compounds of:", "options": ["Iron", "Helium", "Carbon", "Sodium"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Nuclear and Organic Chemistry, and Stewardship of Creation$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,3,2}'::int[], array[$j$40 halves to 20, then to 10.$j$,$j$Alpha particles have 2 protons and 2 neutrons.$j$,$j$Fusion combines nuclei.$j$,$j$Carbon forms the backbone of organic compounds.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 6.4: Nuclear and Organic Chemistry, and Stewardship of Creation$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 30, $j$Unit Quiz 6: Acids and Bases, Reaction Rates, Redox, Nuclear and Organic Chemistry$j$, $j${"questions": [{"q": "Acids turn blue litmus paper:", "options": ["Red", "Black", "Green", "Yellow"]}, {"q": "A solution with pH 11 is:", "options": ["Acidic", "A metal", "Neutral", "Basic"]}, {"q": "Heating a reaction usually makes it:", "options": ["Faster", "Slower", "Stop", "Reverse permanently"]}, {"q": "At equilibrium, the amounts of reactants and products:", "options": ["Stay constant", "Fall to zero", "Increase forever", "Disappear"]}, {"q": "Reduction is the:", "options": ["Gain of protons", "Loss of protons", "Gain of electrons", "Loss of electrons"]}, {"q": "A battery converts:", "options": ["Light to sound", "Electrical energy to nuclear energy", "Chemical energy to electrical energy", "Heat to mass"]}, {"q": "After 3 half lives, what fraction of a radioactive sample remains?", "options": ["One half", "One eighth", "One third", "One sixth"]}, {"q": "Genesis 2:15 teaches humans to dress and keep the garden, which supports:", "options": ["Wasting resources", "Ignoring pollution", "Stewardship of creation", "Avoiding science"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Acids and Bases, Reaction Rates, Redox, Nuclear and Organic Chemistry$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,0,0,2,2,1,2}'::int[], array[$j$Acids turn blue litmus red.$j$,$j$Above 7 is basic.$j$,$j$Higher temperature increases collisions.$j$,$j$Rates are equal, so amounts do not change.$j$,$j$RIG: Reduction Is Gain.$j$,$j$Galvanic cells produce current from chemical change.$j$,$j$Half of half of half is one eighth.$j$,$j$Keeping creation means caring for it.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 6: Acids and Bases, Reaction Rates, Redox, Nuclear and Organic Chemistry$j$ on conflict (item_id) do nothing;
